src = "/Users/dk/lab-data/ai-suite/opencode-models/zai-provider.json"
outdir = "/Users/dk/lab-data/ai-suite/opencode-models"

with open(src) as f:
    data = json.load(f)

# Unwrap from the "zai" wrapper key
provider = data["zai"]
models = provider["models"]

# Top-level keys to include (matching opencode-provider.yaml style)
top_keys = ["api", "doc", "env", "id", "name", "npm", "models"]

def build_doc(provider_base, model_dict):
    """Build an OrderedDict with the same top-level key order as opencode-provider.yaml."""
    doc = {}
    for k in top_keys:
        if k == "models":
            doc["models"] = model_dict
        elif k in provider_base:
            doc[k] = provider_base[k]
    return doc

def is_free(m):
    c = m.get("cost", {})
    return all(v == 0 for v in c.values())

def write_yaml(path, doc):
    with open(path, "w") as f:
        yaml.dump(doc, f, default_flow_style=False, allow_unicode=True, sort_keys=False)
    print(f"wrote {path}")

# 1. Full YAML (all models, original key order within each model)
write_yaml(os.path.join(outdir, "zai-provider.yaml"), build_doc(provider, dict(models)))

# 2. Active: remove deprecated
active_models = {k: v for k, v in models.items() if v.get("status") != "deprecated"}
write_yaml(os.path.join(outdir, "zai-provider-active.yaml"), build_doc(provider, active_models))

# 3. Free: all costs zero
free_models = {k: v for k, v in models.items() if is_free(v)}
write_yaml(os.path.join(outdir, "zai-provider-free.yaml"), build_doc(provider, free_models))

# 4. Free knowledge sorted: free models sorted by knowledge descending (models without knowledge go last)
def knowledge_sort_key(item):
    m = item[1]
    k = m.get("knowledge")
    if k is None:
        return (1, "")
    return (0, k if isinstance(k, str) else str(k))

sorted_free = dict(sorted(free_models.items(), key=knowledge_sort_key, reverse=True))
write_yaml(os.path.join(outdir, "zai-provider-free-knowledge-sorted.yaml"), build_doc(provider, sorted_free))

print("done")
