import json, os, sys
import yaml

SOURCE = os.environ.get(
    "MODELS_JSON",
    os.path.expanduser(
        "~/lab-data/configurations-private/opencode/cache/models.json"
    ),
)
OUTDIR = os.path.dirname(os.path.abspath(__file__))


def is_free(model):
    cost = model.get("cost")
    return cost is not None and all(v == 0 for v in cost.values())


def knowledge_sort_key(item):
    _, model = item
    k = model.get("knowledge")
    return (1, "") if k is None else (0, str(k))


def main():
    with open(SOURCE) as f:
        data = json.load(f)

    gen = 0
    skip = 0

    for pid, pdata in data.items():
        models = pdata.get("models", {})
        free = {k: v for k, v in models.items() if is_free(v)}

        if not free:
            skip += 1
            continue

        sorted_free = dict(
            sorted(free.items(), key=knowledge_sort_key, reverse=True)
        )

        doc = {}
        for k in ["api", "doc", "env", "id", "name", "npm", "models"]:
            if k == "models":
                doc["models"] = sorted_free
            elif k in pdata:
                doc[k] = pdata[k]

        path = os.path.join(OUTDIR, f"{pid}-provider-free-knowledge-sorted.yaml")
        with open(path, "w") as f:
            yaml.dump(doc, f, default_flow_style=False, allow_unicode=True, sort_keys=False)

        gen += 1

    print(f"Generated {gen} files | Skipped {skip} providers with no free models")


if __name__ == "__main__":
    main()
